() => {
  const result = {};
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (/model/i.test(k)) result[k] = localStorage.getItem(k);
  }
  const sel = document.querySelector('select[title*="模型"], select');
  const all = [...document.querySelectorAll('select')].map(s => ({ value: s.value, aria: s.getAttribute('aria-label'), classes: s.className }));
  return { modelKeys: result, selects: all };
}

() => {
  const selects = [...document.querySelectorAll('select')].map(s => ({ value: s.value, options: [...s.options].map(o => o.textContent) }));
  return { stored: localStorage.getItem('app-selected-model'), selects };
}

() => {
  const sel = [...document.querySelectorAll('select')].find(s => s.value === 'ollama::deepseek-r1:8b');
  sel.scrollIntoView({ block: 'center' });
  return sel.value;
}

() => {
  const sel = [...document.querySelectorAll('select')].find(s => s.value === 'ollama::deepseek-r1:8b');
  const wrap = sel.closest('div');
  const outer = wrap.parentElement;
  const svg = outer.querySelector('svg');
  return {
    wrapperHTML: outer.outerHTML.slice(0, 1200),
    hasSvgIcon: !!svg,
    svgClass: svg ? svg.getAttribute('class') : null,
    selectClass: sel.className
  };
}

() => {
  const sel = [...document.querySelectorAll('select')].find(s => s.value === 'ollama::deepseek-r1:8b');
  const wrap = sel.parentElement; // likely a flex container with icon
  const icon = wrap.querySelector('svg');
  return {
    wrapClass: wrap.className,
    wrapHTML: wrap.outerHTML.slice(0, 900),
    iconClass: icon ? icon.getAttribute('class') : null
  };
}
